const initialLesson = (language:string, level:string):GeneratedLesson => {
 const isJava = language === 'Java';
 const code = language === 'Python' ? 'print("Hello, world!")' : isJava ? 'class Main {\n  public static void main(String[] args) {\n    System.out.println("Hello!");\n  }\n}' : language === 'JavaScript' ? 'console.log("Hello, world!");' : language === 'HTML' ? '<h1>Hello, world!</h1>' : language === 'SQL' ? 'SELECT name FROM students;' : language === 'CSS' ? 'h1 { color: purple; }' : language === 'Ruby' ? 'puts "Hello, world!"' : language === 'Go' ? 'package main\nimport "fmt"\nfunc main() { fmt.Println("Hello!") }' : language === 'C' ? '#include <stdio.h>\nint main(void) { printf("Hello!"); return 0; }' : language === 'C++' ? '#include <iostream>\nint main() { std::cout << "Hello!"; }' : language === 'C#' ? 'Console.WriteLine("Hello!");' : language === 'TypeScript' ? 'console.log("Hello, world!");' : language === 'Kotlin' ? 'fun main() { println("Hello!") }' : language === 'Swift' ? 'print("Hello, world!")' : language === 'PHP' ? '<?php echo "Hello!";' : language === 'Dart' ? 'void main() { print("Hello!"); }' : language === 'R' ? 'print("Hello!")' : language === 'Lua' ? 'print("Hello!")' : language === 'Rust' ? 'fn main() { println!("Hello!"); }' : 'section .data\nmsg db "Hello!", 0';
 const command = language === 'Python' || language === 'Swift' || language === 'R' || language === 'Lua' ? 'print' : language === 'Java' ? 'System.out.println' : language === 'JavaScript' || language === 'TypeScript' ? 'console.log' : language === 'HTML' ? '<h1>' : language === 'SQL' ? 'SELECT' : language === 'CSS' ? 'color' : language === 'Ruby' ? 'puts' : language === 'C' ? 'printf' : language === 'C++' ? 'std::cout' : language === 'C#' ? 'Console.WriteLine' : language === 'Go' ? 'fmt.Println' : language === 'Rust' ? 'println!' : language === 'Kotlin' || language === 'Dart' ? 'println' : language === 'PHP' ? 'echo' : 'db';
 return {title:'Your first '+language+' program',concept:'A program is a set of instructions. Let’s start by showing a message on the screen.',explanation:'This first step introduces output: asking the computer to display information. You do not need to memorize everything yet; focus on what each piece does.',example:code,breakdown:[command+' is the part that displays or describes output in this language.','The text inside quotation marks is a string.','Punctuation and letter case matter: follow the example carefully.'],passScore:70,tasks:[
  {type:'choice',prompt:'What is the main idea of this code?',code,options:['It displays or describes a message','It deletes the program','It creates a password','It turns off the computer'],answer:'It displays or describes a message',explanation:'The example demonstrates a basic output instruction.'},
  {type:'order',prompt:'Arrange the main pieces into a simple output instruction.',tokens:language==='Python'?['print','(','"Hi!"',')']:language==='JavaScript'||language==='TypeScript'?['console.log','(','"Hi!"',')',';']:['OUTPUT','(','"Hi!"',')'],answer:language==='Python'?'print("Hi!")':language==='JavaScript'||language==='TypeScript'?'console.log("Hi!");':'OUTPUT("Hi!")',explanation:'Build the instruction from the output command, parentheses, text and closing punctuation.'},
  {type:'blank',prompt:'Fill in the missing output command.',code:language==='Python'?'____("Hi!")':language==='Java'?'System.out.____("Hi!");':language==='JavaScript'?'console.____("Hi!");': '____("Hi!")',answer:language==='Python'?'print':language==='Java'?'println':language==='JavaScript'?'log':command,explanation:'The command is the part that tells the language to show output.'},
  {type:'write',prompt:'In your own words, what does the example do?',answer:'It displays a message',explanation:'The important idea is that the program asks for a message to be shown.'},
  {type:'choice',prompt:'Which part represents text in the example?',options:['The words inside quotation marks','The file name','The keyboard','The line number'],answer:'The words inside quotation marks',explanation:'Quotation marks show that the enclosed characters are text.'},
  {type:'fix',prompt:'The instruction is missing its text. Complete the code.',code:language==='Python'?'print(____)':language==='JavaScript'?'console.log(____);':'OUTPUT(____)',answer:'"Hi!"',explanation:'The message must be included as text, usually between quotation marks.'},
  {type:'order',prompt:'Put these ideas in a sensible order.',tokens:['Choose an output command','Add the message','Close the instruction'],answer:'Choose an output command|Add the message|Close the instruction',explanation:'Start with the command, add the value, and close the expression or statement.'}
 ]};
};

